<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot\Views; use Pterodactyl\Models\User; use Pterodactyl\Models\Dezerx\DiscordBot; use Pterodactyl\Services\Dezerx\DiscordBot\Ui; use Pterodactyl\Services\Dezerx\DiscordBot\Style; use Pterodactyl\Services\Dezerx\DiscordBot\Format; use Pterodactyl\Services\Dezerx\DiscordBot\BotConfig; use Pterodactyl\Services\Dezerx\DiscordBot\BotSettings; class Cards { public const ACCOUNT_PAGE = 'account/discord'; public static function notice(string $title, string $body, string $tone = 'info', array $buttons = []): array { $accent = match ($tone) { 'error' => Ui::OFFLINE, 'success' => Ui::RUNNING, 'warning' => Ui::PENDING, default => Style::current()->accent(), }; return Ui::message([ Ui::container([ Ui::text("### {$title}\n{$body}"), $buttons === [] ? null : Ui::row($buttons), ], $accent), ]); } public static function error(string $message, array $buttons = []): array { return self::notice('That did not work', $message, 'error', $buttons); } public static function slowDown(int $seconds, bool $shared = false): array { return self::notice('Slow down a little', $shared ? "This bot is taking a lot of requests right now. Try again in {$seconds}s." : "That is a lot of requests in a short time. Try again in {$seconds}s.", 'warning'); } public static function linkFirst(): array { $style = Style::current(); return Ui::message([ Ui::container([ Ui::section( "## Link your account first\nThis bot works as you on **" . Format::escape(BotConfig::panelName()) . "**, so it needs to know which account is yours.\n" . "**1.** Open the Discord page in the panel.\n**2.** Press **Connect Discord** and approve it.\n**3.** Come back and run the command again.", Ui::thumbnail($style->logo(BotConfig::panelLogo())), ), Ui::row([ Ui::link(BotConfig::panelUrl(self::ACCOUNT_PAGE), 'Open the Discord page'), ]), ], $style->accent()), ]); } public static function disabled(): array { return self::notice('The bot is switched off', 'An administrator of **' . Format::escape(BotConfig::panelName()) . '** has turned the Discord bot off. Nothing here works until it is turned back on.', 'warning'); } public static function wrongBot(DiscordBot $bot): array { if (!$bot->isGlobal()) { return self::notice('This bot is off', 'Its owner\'s panel no longer lets people run their own bots, so it has stopped answering.', 'warning'); } return self::notice('Use your own bot', 'This panel is set up for everybody to run their own bot. Set yours up from the Discord page in the panel.', 'warning', [ Ui::link(BotConfig::panelUrl(self::ACCOUNT_PAGE), 'Open the Discord page'), ]); } public static function switchedOff(string $command): array { return self::notice('That command is switched off', '`/' . $command . '` is turned off for this bot.', 'warning'); } public static function notAllowed(string $command, array $roles, bool $personal, string $userId = ''): array { $hint = $personal && ctype_digit($userId) ? "\n-# Your Discord ID is `{$userId}`. The owner can give you access on the Discord page in the panel." : ''; if (!$personal || $roles === []) { return self::notice('Not for you', 'Only the owner of this bot and the people they added can use `/' . $command . '`.' . $hint, 'error'); } $mentions = implode(' ', array_map(fn (string $id) => '<@&' . $id . '>', array_slice($roles, 0, 10))); return self::notice('You need a role for that', '`/' . $command . '` is open to ' . $mentions . ', the bot\'s owner and the people they added.' . $hint, 'error'); } public static function revoked(): array { return self::notice('The bot has lost access', 'The API key this bot acts with was deleted, so it can no longer do anything. Turn it back on from the Discord page in the panel.', 'error', [ Ui::link(BotConfig::panelUrl(self::ACCOUNT_PAGE), 'Open the Discord page'), ]); } public static function help(?string $who, bool $linked, bool $personal = false): array { $style = Style::current(); $name = Format::escape(BotConfig::panelName()); $groups = []; foreach (BotSettings::CATALOGUE as $command => $meta) { if ($command === 'help' || !Style::can($command)) { continue; } $label = $command === 'alerts' ? '`/alerts add` · `list` · `remove`' : '`/' . $command . '`'; $groups[$meta['group']][] = $label . ' ' . lcfirst(rtrim($meta['description'], '.')); } $components = [ Ui::gallery([$style->banner(BotConfig::banner())]), Ui::section( "## {$name} on Discord\nYour servers, one command away. Every action runs as " . ($personal ? 'the bot owner\'s panel account, with exactly the permissions it has there.' : 'your own panel account, with exactly the permissions you have there.') . "\n-# " . ($who === null ? ($linked ? 'Linked' : 'You are not linked yet. Start from the Discord page in the panel.') : 'Acting as **' . Format::escape($who) . '**'), Ui::thumbnail($style->logo(BotConfig::panelLogo())), ), Ui::divider(), ]; foreach ($groups as $group => $lines) { $components[] = Ui::text('### ' . $group . "\n" . implode("\n", $lines)); } if ($groups === []) { $components[] = Ui::text('No commands are open to you on this bot.'); } $components[] = Ui::divider(); $components[] = Ui::row([ $linked && Style::can('servers') ? Ui::button('dzb:srv:1', 'My servers', Ui::PRIMARY) : null, Ui::link(BotConfig::panelUrl(), 'Open the panel'), Ui::link(BotConfig::panelUrl(self::ACCOUNT_PAGE), 'Bot settings'), ]); $components[] = Ui::text('-# ' . $style->footer()); return Ui::message([Ui::container($components, $style->accent())]); } public static function account(User $user, int $servers, ?string $avatar, ?string $discord, ?string $linkedAt, bool $personal, ?string $notice = null): array { $style = Style::current(); $lines = [ '**Panel account** ' . Format::escape($user->username), '**Email** ' . Format::escape(Format::mask($user->email)), '**Servers it can reach** ' . $servers, ]; if ($discord !== null) { $lines[] = '**Discord** ' . Format::escape($discord) . ($linkedAt !== null ? ' · linked ' . Format::timestamp($linkedAt, 'D') : ''); } if ($user->root_admin) { $lines[] = '**Role** Administrator'; } return Ui::message([ Ui::container([ $notice === null ? null : Ui::text($notice), Ui::section([ '## ' . Format::escape(trim($user->name_first . ' ' . $user->name_last) ?: $user->username), implode("\n", $lines), '-# ' . ($personal ? 'This bot acts as its owner, with its own API key.' : 'Actions run with your own API key, listed under API Credentials.') . ' · ' . $style->footer(), ], Ui::thumbnail($avatar)), Ui::row([ Style::can('servers') ? Ui::button('dzb:srv:1', 'Servers', Ui::PRIMARY) : null, Ui::link(BotConfig::panelUrl('account'), 'Open the account'), !$personal && Style::can('unlink') ? Ui::button('dzb:unlink', 'Unlink', Ui::DANGER) : null, ]), ], $style->accent()), ]); } public static function unlinkConfirm(): array { return self::notice('Unlink this Discord?', 'The bot stops acting for you straight away, its API key is deleted, and any alerts you set up stop. You can link again from the panel at any time.', 'warning', [ Ui::button('dzb:unlink:yes', 'Unlink', Ui::DANGER), Ui::button('dzb:account', 'Keep it', Ui::SECONDARY), ]); } } 